const KB = (t, h) => `<div class="keybox"><b class="t">${t}</b>${h}</div>`;
const T2 = (h, rows) => tbl([h, ...rows], { headRow: true });
const A = s => AR(s);                         // نصٌّ عشريٌّ كما هو (مع الأصفار)
const html = (P, h) => ({ ...P, html: (P.html || '') + h });
const r10 = (x, p) => { const f = 10 ** p; return Math.round((x + Math.sign(x) * 1e-9) * f) / f; };
const ss = (e, V) => { let s = e.replace(/ـ/g, ''); s = s.replace(/([\dء-ي])\s*(?=[ء-ي(])/g, '$1 × '); return s.replace(/[ء-ي]/g, c => c in V ? String(V[c]) : c); };
const eqQ = (tag, eq, v, x, vals, o = {}) => vals ? ch(tag, `حدّدْ حلَّ المعادلة ${R(eq)} من القيم: ${vals.map(AR).join('، ')}`, vals.map(AR), vals.indexOf(x), { sol: [`نعوّضُ ${v} = ${AR(x)}: ${R(ss(eq, { [v]: x }))} ✓`], ...o }) : num(tag, `حُلَّ المعادلةَ ذهنيًّا: ${R(eq)}`, x, { sol: [`${R(ss(eq, { [v]: x }))} ✓`], ...o });

/* ═════════ الكلماتُ والمنازل ═════════ */
const ONES = ['', 'واحد', 'اثنان', 'ثلاثة', 'أربعة', 'خمسة', 'ستّة', 'سبعة', 'ثمانية', 'تسعة'], TENS = ['', 'عشرة', 'عشرون', 'ثلاثون', 'أربعون', 'خمسون', 'ستّون', 'سبعون', 'ثمانون', 'تسعون'], HUN = ['', 'مئة', 'مئتان', 'ثلاث مئة', 'أربع مئة', 'خمس مئة', 'ستّ مئة', 'سبع مئة', 'ثماني مئة', 'تسع مئة'];
function w99(n) { if (n < 10) return ONES[n]; if (n === 10) return 'عشرة'; if (n === 11) return 'أحد عشر'; if (n === 12) return 'اثنا عشر'; if (n < 20) return ONES[n - 10] + ' عشر'; const u = n % 10, t = Math.floor(n / 10); return u ? ONES[u] + ' و' + TENS[t] : TENS[t]; }
export function intWords(n) { if (n === 0) return 'صفر'; const P = []; const th = Math.floor(n / 1000), h = Math.floor(n % 1000 / 100), r = n % 100;
  if (th) P.push(th === 1 ? 'ألف' : th === 2 ? 'ألفان' : th <= 10 ? w99(th) + ' آلاف' : w99(th) + ' ألف'); if (h) P.push(HUN[h]); if (r) P.push(w99(r)); return P.join(' و'); }
const DEN = ['عشرة', 'مئة', 'ألف', 'عشرة آلاف', 'مئة ألف'];
export function decWords(s) { s = String(s); const [w, f = ''] = s.split('.'); const W = +w, F = +f || 0, d = f.length; const fp = d && F ? `${intWords(F)} من ${DEN[d - 1]}` : ''; return W && fp ? `${intWords(W)}، و${fp}` : W ? intWords(W) : fp || 'صفر'; }
const PL = ['عشرات الآلاف', 'الآلاف', 'المئات', 'العشرات', 'الآحاد', 'الأجزاء من عشرة', 'الأجزاء من مئة', 'الأجزاء من ألف', 'الأجزاء من عشرة آلاف'];
const PV = [10000, 1000, 100, 10, 1, 0.1, 0.01, 0.001, 0.0001];
export function expanded(s) { s = String(s); const [w, f = ''] = s.split('.'); const T = []; [...w].forEach((c, i) => { const p = 10 ** (w.length - 1 - i); if (!(w === '0')) T.push(`(${c} × ${p})`); }); [...f].forEach((c, i) => T.push(`(${c} × ${['0.1', '0.01', '0.001', '0.0001', '0.00001'][i]})`)); return T.join(' + '); }
const expHTML = s => R(expanded(s).replace(/0\.(\d+)/g, m => m));
const tf = (x) => String(x);

/* ── أداة: جدولُ المنازلِ ونموذجُ الكسرِ العشريّ ── */
function gridSVG(v) { const n = Math.max(1, Math.ceil(v - 1e-9)); let g = '', x0 = 0; const W0 = n * 118 - 8; for (let k = 0; k < n; k++) { x0 = W0 - (k + 1) * 118 + 8; const part = Math.max(0, Math.min(1, v - k)), cells = Math.round(part * 100); for (let i = 0; i < 100; i++) { const c = i % 10, r = Math.floor(i / 10), on = c * 10 + (9 - r) < cells; g += `<rect x="${x0 + (9 - c) * 11}" y="${r * 11}" width="10" height="10" fill="${on ? (part >= 1 ? '#9fb3e8' : '#9ed39b') : '#fff'}" stroke="#888" stroke-width=".5"/>`; } } return `<svg viewBox="0 0 ${W0} 110" style="max-width:${Math.min(400, n * 130)}px;width:100%;direction:ltr">${g}</svg>`; }
function placeTable(s) { s = String(s); const [w, f = ''] = s.split('.'); const W = w.padStart(4, '0').slice(-4), F = f.padEnd(4, '0').slice(0, 4); const H = PL.slice(1); const D = [...W, ...F]; return `<div class="pvw"><table class="tb pvt"><tr>${PV.slice(1).map(p => `<th>${fmt(p)}</th>`).join('')}</tr><tr>${H.map(h => `<th class="pvh">${h}</th>`).join('')}</tr><tr>${D.map((d, i) => `<td class="${i === 3 ? 'pvd' : ''}">${AR(d)}</td>`).join('')}</tr></table></div>`; }
function placeTool(el, start = '1.75') {
  el.innerHTML = `<div class="row">العدد: ${ansInput('مثل: ١,٧٥', '140px')}<button class="btn s sm" data-a="go">اعرضْ</button></div><div class="plb"></div>`;
  const show = s => { const v = parseNum(s); if (isNaN(v) || v < 0 || v >= 10000) return; s = toW(s).replace(/[٫,]/g, '.').replace(/[^\d.]/g, ''); if (s.startsWith('.')) s = '0' + s;
    $('.plb', el).innerHTML = `<div class="meta">جدولُ المنازلِ العشريّة (الفاصلةُ بعدَ منزلةِ الآحاد):</div>${placeTable(s)}${v <= 3 ? `<div class="meta">نموذجُ الكسرِ العشريّ:</div>${gridSVG(v)}` : ''}<table class="tb"><tr><th>الصيغةُ القياسيّة</th><td><b>${A(s)}</b></td></tr><tr><th>الصيغةُ اللفظيّة</th><td>${decWords(s)}</td></tr><tr><th>الصيغةُ التحليليّة</th><td>${expHTML(s)}</td></tr></table>`; };
  $('input', el).value = A(start); $('[data-a="go"]', el).onclick = () => show($('input', el).value); show(start);
}
/* ── أداة: المقارنةُ بمحاذاةِ المنازل ── */
function cmpTool(el, a = '2.64', b = '2.63') {
  el.innerHTML = `<div class="row">${ansInput('العدد الأوّل', '110px')} و ${ansInput('العدد الثاني', '110px')}<button class="btn s sm" data-a="go">قارنْ</button></div><div class="cmpb"></div>`;
  const I = $$('input', el); I[0].value = A(a); I[1].value = A(b);
  const go = () => { const S = I.map(i => toW(i.value).replace(/[٫,]/g, '.').replace(/[^\d.]/g, '')); if (S.some(s => !s || isNaN(+s))) return; const sp = S.map(s => s.includes('.') ? s.split('.') : [s, '']); const wl = Math.max(...sp.map(p => p[0].length)), fl = Math.max(...sp.map(p => p[1].length)); const P = sp.map(p => p[0].padStart(wl, ' ') + (fl ? '.' + p[1].padEnd(fl, '0') : ''));
    let k = -1; for (let i = 0; i < P[0].length; i++) if (P[0][i] !== P[1][i]) { k = i; break; } const va = +S[0], vb = +S[1], sym = va > vb ? '&gt;' : va < vb ? '&lt;' : '=';
    $('.cmpb', el).innerHTML = `<div class="cmpg">${P.map((p, j) => `<div>${[...p].map((c, i) => `<span class="${i === k ? 'hl' : ''} ${c === '0' && i >= (sp[j][0].length + 1 + sp[j][1].length) + (wl - sp[j][0].length) ? 'zp' : ''}">${c === ' ' ? '&nbsp;' : AR(c)}</span>`).join('')}</div>`).join('')}</div><div class="fb">${k < 0 ? 'الكسرانِ متساويان (الأصفارُ المضافةُ لا تغيّرُ القيمة).' : `أوّلُ منزلةٍ يختلفُ فيها الرقمان: <b>${AR(P[0][k])}</b> و<b>${AR(P[1][k])}</b>`}<div class="big">${A(S[0])} ${sym} ${A(S[1])}</div></div>`; };
  $('[data-a="go"]', el).onclick = go; go();
}
/* ── أداة: التقريبُ على خطِّ الأعداد ── */
function roundTool(el, x0 = '1.324') {
  el.innerHTML = `<div class="row">العدد: ${ansInput('مثل: ٩٩,٩٦', '120px')} قرّبْ إلى: <select class="rp"><option value="0">أقرب عددٍ كلّيّ</option><option value="1">أقرب جزءٍ من عشرة</option><option value="2">أقرب جزءٍ من مئة</option><option value="3">أقرب جزءٍ من ألف</option></select><button class="btn s sm" data-a="go">قرّبْ</button></div><div class="rb"></div>`;
  $('input', el).value = A(x0);
  const go = () => { const s = toW($('input', el).value).replace(/[٫,]/g, '.').replace(/[^\d.]/g, ''), x = +s, p = +$('.rp', el).value; if (!s || isNaN(x)) return; const f = 10 ** p, lo = Math.floor(x * f + 1e-9) / f, hi = r10(lo + 1 / f, p), r = r10(x, p);
    const [w, fr = ''] = s.split('.'); const digs = w + fr; const ui = w.length - 1 + p, nxt = digs[ui + 1] || '0';
    const W = 360, X = v => 30 + (v - lo) / (hi - lo) * 300; let g = `<line x1="20" x2="340" y1="40" y2="40" stroke="#333"/>`; for (let i = 0; i <= 10; i++) { const v = lo + (hi - lo) * i / 10; g += `<line x1="${X(v)}" x2="${X(v)}" y1="${i % 5 ? 35 : 30}" y2="${i % 5 ? 45 : 50}" stroke="#333"/>`; } g += `<text x="${X(lo)}" y="66" text-anchor="middle" font-size="12">${fmt(lo, p)}</text><text x="${X(hi)}" y="66" text-anchor="middle" font-size="12">${fmt(hi, p)}</text><text x="${X((lo + hi) / 2)}" y="66" text-anchor="middle" font-size="10" fill="#888">المنتصف</text><circle cx="${X(Math.min(hi, Math.max(lo, x)))}" cy="40" r="6" fill="#e85a4f"/><text x="${X(Math.min(hi, Math.max(lo, x)))}" y="22" text-anchor="middle" font-size="12" font-weight="700" fill="#e85a4f">${A(s)}</text>`;
    $('.rb', el).innerHTML = `<div class="big">${[...digs].map((c, i) => `${i === w.length ? ',' : ''}<span class="${i === ui ? 'ul' : i === ui + 1 ? 'nx' : ''}">${AR(c)}</span>`).join('')}</div><div class="meta">ضعْ خطًّا تحتَ رقمِ المنزلة، وانظرْ إلى الرقمِ عن يمينِه: <b>${AR(nxt)}</b> ${+nxt >= 5 ? '≥ ٥ ← نضيفُ ١' : '≤ ٤ ← يبقى كما هو'}</div><svg viewBox="0 0 ${W} 80" style="width:100%;max-width:420px;direction:ltr">${g}</svg><div class="fb">الناتج: <b>${fmt(r, p)}</b></div>`; };
  $('[data-a="go"]', el).onclick = go; go();
}

/* ═════════ أنواعُ الأسئلة ═════════ */
const nearMiss = s => { const v = +s, d = (String(s).split('.')[1] || '').length; return [String(r10(v * 10, Math.max(0, d - 1))), String(r10(v / 10, d + 1))]; };
const wordQ = (tag, s, o = {}) => { const opts = shuf([...new Set([decWords(s), ...nearMiss(s).map(decWords)])]).slice(0, 3); if (!opts.includes(decWords(s))) opts[0] = decWords(s); return mcq(tag, o.text || `اكتبِ الكسرَ العشريَّ <b>${A(s)}</b> بالصيغةِ اللفظيّة:`, opts, opts.indexOf(decWords(s)), { title: A(s), skill: 'words', sol: [`${A(s)}: ${decWords(s)}`], hints: ['اقرأِ العددَ الكلّيّ، ثم «و»، ثم الجزءَ العشريَّ كعددٍ كلّيّ.', 'اسمُ آخرِ منزلةٍ يحدّدُ المقام: عشرة، مئة، ألف…'], html: placeTable(s), ...o }); };
const expOK = s => raw => { const t = toW(raw).replace(/[٫,]/g, '.').replace(/\s/g, ''); if (!/[×x*]/.test(t)) return { empty: true, msg: 'اكتبْ مجموعَ نواتجِ ضربِ كلِّ رقمٍ في قيمةِ منزلتِه، مثل (٣ × ١٠) + (٥ × ١)' }; let v; try { v = evalExpr(raw); } catch (e) { return { empty: true, msg: 'تأكّدْ من الأقواسِ والعمليّات.' }; } if (Math.abs(v - +s) > 1e-9) return { ok: false, msg: `قيمةُ ما كتبتَ ${fmt(v)} وليستْ ${A(s)}.` }; const terms = t.replace(/[()]/g, '').split('+'); const bad = terms.some(q => { const f = q.split(/[×x*]/); if (f.length !== 2) return true; const [a, b] = f.map(Number); const isP = z => [10000, 1000, 100, 10, 1, 0.1, 0.01, 0.001, 0.0001].includes(z); return !((a <= 9 && Number.isInteger(a) && isP(b)) || (b <= 9 && Number.isInteger(b) && isP(a))); }); return bad ? { ok: false, msg: 'القيمةُ صحيحة، لكنْ اكتبْ كلَّ حدٍّ في صورة (رقم × قيمة المنزلة).' } : { ok: true }; };
const stdQ = (tag, words, s, o = {}) => fld(tag, o.text || `اكتبْ «${words}» بالصيغتينِ القياسيّةِ والتحليليّة:`, [['القياسيّة', +s, 'num', { w: '130px' }], ['التحليليّة', 0, 'fn', { fn: expOK(s), show: expHTML(s), kp: 'expr', w: '100%', ph: 'مثل: (٣ × ١٠) + (٥ × ١) + (٢ × ٠,١)' }]], { title: A(s), skill: 'std', sol: [`القياسيّة: ${A(s)}`, `التحليليّة: ${expHTML(s)}`], ...o });
function placeQ2(tag, s, pos, o = {}) { s = String(s); const dot = s.indexOf('.'); const off = dot < 0 ? s.length - 1 - pos : pos < dot ? dot - 1 - pos : -(pos - dot); const name = off >= 0 ? ['الآحاد', 'العشرات', 'المئات', 'الآلاف'][off] : PL[4 - off]; const opts = shuf([name, ...shuf(PL.slice(3, 9).filter(x => x !== name)).slice(0, 3)]); return mcq(tag, o.text || `سمِّ منزلةَ الرقمِ الذي تحتَه خطٌّ: <span class="big">${[...s].map((c, k) => `<span class="${k === pos ? 'ul' : ''}">${c === '.' ? ',' : AR(c)}</span>`).join('')}</span>`, opts, opts.indexOf(name), { skill: 'place', sol: [`الرقمُ في منزلةِ ${name}`], ...o }); }
const cmpD = (tag, a, b, o = {}) => cmp(tag, +a, +b, { ha: `<b class="n">${A(a)}</b>`, hb: `<b class="n">${A(b)}</b>`, skill: 'cmpd', mount: el => { el.innerHTML = '<button class="lnk">🔍 حاذِ المنازلَ وقارنْ</button>'; $('button', el).onclick = () => cmpTool(el, a, b); }, sol: [`نحاذي المنازلَ ونضيفُ أصفارًا: ${A(a)} و ${A(b)}، ثم نقارنُ من اليسار.`], ...o });
const orderQ = (tag, L, asc = true, o = {}) => { const S = L.slice().sort((x, y) => asc ? x - y : y - x); return lst(tag, o.text || `رتّبِ الكسورَ العشريّةَ ${asc ? 'تصاعديًّا (من الأصغرِ إلى الأكبر)' : 'تنازليًّا (من الأكبرِ إلى الأصغر)'}: ${L.map(x => A(x)).join('، ')}`, S, { skill: 'order', ph: 'افصلْ بالفاصلة «،»', sol: [S.map(x => A(x)).join('، ')], hints: ['اكتبِ الأعدادَ تحتَ بعضِها مع محاذاةِ الفواصل.', 'أضفْ أصفارًا حتى يتساوى عددُ المنازلِ العشريّة، ثم قارنْ.'], ...o }); };
const PN = ['أقرب عددٍ كلّيّ', 'أقرب جزءٍ من عشرة', 'أقرب جزءٍ من مئة', 'أقرب جزءٍ من ألف', 'أقرب جزءٍ من عشرة آلاف'];
const roundQ = (tag, s, p, o = {}) => { const x = +s, r = p < 0 ? Math.round(x / 10) * 10 : r10(x, p); return num(tag, o.text || `قرّبْ <b>${A(s)}</b> إلى ${p < 0 ? 'أقربِ عشرة' : PN[p]}.`, r, { title: A(s), skill: 'round', sol: [`${A(s)} ≈ ${p < 0 ? AR(r) : fmt(r, p)}`], hints: ['ضعْ خطًّا تحتَ رقمِ المنزلةِ المطلوبة.', 'إذا كانَ الرقمُ عن يمينِه ٥ أو أكبر فأضفْ ١، وإلّا فيبقى كما هو.'], mount: p >= 0 ? el => { el.innerHTML = '<button class="lnk">📏 أرني على خطِّ الأعداد</button>'; $('button', el).onclick = () => roundTool(el, s); } : undefined, ...o }); };
const front = v => { const p = 10 ** Math.floor(Math.log10(v)); return Math.floor(v / p + 1e-9) * p; };
const estQ = (tag, terms, op, how, o = {}) => { const v = terms.map(Number); let R0, sol;
  if (how === 'round') { const r = v.map(x => Math.round(x)); R0 = op === '-' ? r[0] - r[1] : sum(r); sol = `نقرّبُ إلى أقربِ عددٍ كلّيّ: ${r.map(AR).join(op === '-' ? ' − ' : ' + ')} = ${AR(R0)}`; }
  else if (how === 'cluster') { const c = o.c; R0 = c * v.length; sol = `الأعدادُ قريبةٌ من ${AR(c)}: ${AR(v.length)} × ${AR(c)} = ${AR(R0)}`; }
  else { const f = v.map(front); R0 = op === '-' ? f[0] - f[1] : sum(f); sol = `نثبّتُ الرقمَ في المنزلةِ اليسرى ونعتبرُ الباقيَ أصفارًا: ${f.map(AR).join(op === '-' ? ' − ' : ' + ')} = ${AR(R0)}`; }
  return num(tag, o.text || `قدّرْ ناتجَ ${op === '-' ? 'الطرح' : 'الجمع'} مستعملًا ${how === 'round' ? 'التقريب' : how === 'cluster' ? 'تجمّعَ البيانات' : 'التقديرَ للحدِّ الأدنى'}: ${terms.map(A).join(op === '-' ? ' − ' : ' + ')}`, R0, { skill: 'est', sol: [sol, `(الناتجُ الفعليّ ${fmt(op === '-' ? v[0] - v[1] : sum(v))})`], hints: [how === 'round' ? 'قرّبْ كلَّ عددٍ إلى أقربِ عددٍ كلّيّ.' : how === 'cluster' ? 'الأعدادُ متقاربة؛ اضربْ العددَ القريبَ منها في عددِها.' : 'خذِ الرقمَ الأكبرَ منزلةً فقط واجعلِ الباقيَ أصفارًا.'], ...o }); };

/* ═════════ المولّدات ═════════ */
const rdec = (wmax, d) => { const w = rnd(0, wmax), f = rnd(1, 10 ** d - 1); return `${w}.${String(f).padStart(d, '0')}`; };
const G = {
  words(L) { return wordQ('', rdec(L ? 99 : 9, rnd(1, L === 2 ? 4 : 2))); },
  std(L) { const s = rdec(L ? 99 : 9, rnd(1, L === 2 ? 4 : 3)); return stdQ('', decWords(s), s); },
  place(L) { const s = rdec(L ? 999 : 99, rnd(2, 4)); let i; do { i = rnd(0, s.length - 1); } while (s[i] === '.'); return placeQ2('', s, i); },
  cmpd(L) { const a = rdec(L ? 20 : 9, rnd(1, 3)); let b; if (L === 2 && Math.random() < .3) b = a + '0'; else { const d = (a.split('.')[1] || '').length; b = String(r10(+a + pick([-1, 1]) * pick([0.1, 0.01, 0.001]).toFixed(3) * rnd(1, 9), Math.min(4, d + rnd(0, 1)))); if (+b < 0) b = a.replace(/\d$/, '0'); } return cmpD('', a, b); },
  order(L) { const base = rnd(1, L ? 40 : 9); const S = new Set(); while (S.size < (L ? 5 : 4)) S.add(String(r10(base + rnd(-90, 90) / pick([10, 100, 1000]), 3))); return orderQ('', [...S].map(Number), Math.random() < .6); },
  round(L) { const p = L === 0 ? rnd(0, 1) : rnd(0, 3), s = rdec(L ? 99 : 20, Math.min(4, p + rnd(1, 2))); return roundQ('', s, p); },
  est(L) { const how = L === 0 ? 'round' : pick(['round', 'front', 'cluster']); if (how === 'cluster') { const c = pick([5, 10, 20, 50, 100]), n = rnd(3, 4), t = Array.from({ length: n }, () => String(r10(c + rnd(-40, 40) / 100 * c / 5, 2))); return estQ('', t, '+', how, { c }); } const op = pick(['+', '-']); let a = rnd(1000, L === 2 ? 50000 : 9000) / 100, b = rnd(100, Math.floor(a * 100)) / 100; return estQ('', [String(a), String(b)], op, how); }
};
