/* ═════════ ٣-١٠ خطّةُ حلِّ المسألة: التحقّقُ من معقوليّةِ الإجابة ═════════ */
units['3-10'] = { kind: 'lesson', title: 'خطة حل المسألة: التحقق من معقولية الإجابة', idea: 'أحلُّ المسائلَ باستعمالِ خطّةِ «التحقّقِ من معقوليّةِ الإجابة».', vocab: [['معقوليّةُ الإجابة', 'استعمالُ التقديرِ للتأكّدِ من أنّ الإجابةَ مناسبةٌ للمسألة.']],
  intro: [{ h: 'مها: أتحقّقُ من معقوليّةِ الإجابة', p: 133, html: '<p><b>مها:</b> قمتُ بكتابةِ خمسِ صفحاتٍ من قصّةٍ قصيرةٍ على الحاسوب. إذا كانَ يمكنُني كتابةُ القصّةِ خلالَ ٧٢ دقيقة؛ فأيٌّ ممّا يأتي يعدُّ تقديرًا مناسبًا للزمنِ المتبقّي لإكمالِ كتابةِ القصّة: ٤٠ دقيقة، ٥٠ دقيقة، ٦٠ دقيقة؟</p>' + T2(['رقمُ الصفحة', '١', '٢', '٣', '٤', '٥'], [['الزمن (دقيقة)', '٥,٢٠', '٤,٦٠', '٥,٧٥', '٤,٤٠', '٤,٥٠']]) + tbl([['افهمْ', 'أنتَ تعرفُ زمنَ كتابةِ كلِّ صفحةٍ من الصفحاتِ الخمس، والزمنَ الكلّيَّ لكتابةِ القصّة. والمطلوبُ معرفةُ التقديرِ المعقولِ للزمنِ المتبقّي لإكمالِ كتابتِها.'], ['خطّطْ', 'قدّرْ زمنَ كتابةِ كلِّ صفحة، ثم اجمعِ الأزمنةَ التقديريّة، واطرحْ هذا المجموعَ من الزمنِ الكلّيّ (٧٢ دقيقة).'], ['حُلّ', '٥ + ٥ + ٦ + ٤ + ٥ = ٢٥؛ وبما أنّ ٧٢ − ٢٥ = ٤٧؛ لذا فالتقديرُ المعقولُ للزمنِ المتبقّي هو ٥٠ دقيقة.'], ['تحقّقْ', 'بما أنّ ٥,٢٠ + ٤,٦٠ + ٥,٧٥ + ٤,٤٠ + ٤,٥٠ = ٢٤,٤٥ و٧٢ − ٢٤,٤٥ = ٤٧,٥٥، فإنّ التقدير (٥٠ دقيقة) معقول.']]) }],
  examples: [mcq('المسألة', 'أيُّ تقديرٍ هو الأنسبُ للزمنِ المتبقّي لإكمالِ كتابةِ القصّة؟', ['٤٠ دقيقة', '٥٠ دقيقة', '٦٠ دقيقة'], 1, { cfu: true, p: 133, sol: ['٧٢ − (٥ + ٥ + ٦ + ٤ + ٥) = ٤٧ ≈ ٥٠'] }),
    open('١', 'صِفْ موقفًا قمتَ فيه بتحديدِ إجابةٍ معقولةٍ للمسألة، فساعدَكَ ذلك على حلِّها.', 'مثال: عندَ الشراءِ قدّرتُ مجموعَ الأسعارِ لأتأكّدَ أنّ المبلغَ الذي معي يكفي.', { cfu: true }),
    open('٢', 'اكتبْ مسألةً يمكنُ حلُّها بتحديدِ إجابةٍ معقولة، ثم وضّحِ الخطواتِ التي تتّبعُها لحلِّ المسألة.', 'مثال: معي ٢٠ ريالًا، وأريدُ شراءَ ٣ دفاترَ سعرُ الواحدِ ٥,٩٠ ريالات. التقدير: ٣ × ٦ = ١٨ < ٢٠؛ إذن المبلغُ يكفي.', { cfu: true })],
  ex: [['🧩 مسائلُ متنوّعة', 134, [
    mcq('٣', 'ملابس: أرادتْ آمنةُ شراءَ قميصين، خلالَ فترةِ التخفيضات، ثمنُ الواحدِ منهما ٣٤,٩٥ ريالًا، و٣ أزواجٍ من الجواربِ ثمنُ الواحدِ منها ٧,٩٥ ريالات. فهلْ تحتاجُ أن توفّرَ ١٠٠ ريال، أم ١٥٠ ريالًا لشراءِ ذلك؟', ['١٠٠ ريال', '١٥٠ ريالًا'], 0, { sol: ['٢ × ٣٥ + ٣ × ٨ = ٧٠ + ٢٤ = ٩٤ < ١٠٠ (الفعليّ ٩٣,٧٥)'] }),
    mcq('٤', 'نفقات: سجّلَ أبو حمدٍ ما أنفقَه خلالَ خمسةِ أيّام: الأحد ٩٢، الإثنين ١٠٧,٥٠، الثلاثاء ٧٥، الأربعاء ٦٣,٥٠، الخميس ١١١,٥٠ ريالًا. فإذا أصبحتِ النفقاتُ في الأسبوعِ الثاني مثلَي ما كانتْ عليه في الأسبوعِ الأوّل. فأيُّهما أكثرُ معقوليّةً لما أنفقَه أبو حمدٍ في الأسبوعِ الثاني؛ ٧٠٠ ريال أم ٩٠٠ ريال؟', ['٧٠٠ ريال', '٩٠٠ ريال'], 1, { sol: ['٩٠ + ١١٠ + ٨٠ + ٦٠ + ١١٠ = ٤٥٠، و٢ × ٤٥٠ = ٩٠٠'] }),
    mcq('٥', 'أثواب: يحتاجُ خيّاطٌ إلى ٣٣,٥ مترًا من القماشِ لعملِ ١٠ أثواب، فأيُّهما أكثرُ معقوليّةً لعملِ ٥٠ ثوبًا؛ ١٥٠ مترًا أم ١٧٥ مترًا؟', ['١٥٠ مترًا', '١٧٥ مترًا'], 1, { sol: ['٥ × ٣٣,٥ = ١٦٧,٥ ≈ ١٧٥'] }),
    num('٦', 'اصطفاف: بكم طريقةٍ يمكنُ أن يصطفَّ ٤ طلابٍ على خطٍّ واحد، على أن يقفَ اثنانِ منهم متجاورين؟', 12, { sol: ['نعاملُ الاثنينِ المتجاورين كطالبٍ واحد: ٣ × ٢ × ١ = ٦ طرق، وكلٌّ منها بترتيبين للاثنين: ٦ × ٢ = ١٢'], hints: ['أنشئْ جدولًا بجميعِ الترتيبات.'] }),
    num('٧', 'بيض: لدى صالحٍ مجموعةٌ من الدجاجِ البيّاض. فإذا كانَ معدّلُ ما يجمعُه من البيضِ يوميًّا ٧ بيضات. فكم بيضةً يجمعُ في ٨ سنواتٍ (السنةُ القمريّة = ٣٥٤ يومًا تقريبًا)؟', 19824, { sol: ['٧ × ٣٥٤ × ٨ = ١٩٨٢٤ بيضة'] }),
    fld('٨', 'أساور: تنتجُ سارةُ نوعين من الأساور (صغيرة وكبيرة)، فتبيعُ الأسورةَ الصغيرةَ بـ ٣,٢٥ ريالات، والكبيرةَ بـ ٥,٧٥ ريالات، إذا باعتْ أساورَ بمبلغ ٥٦,٥٠ ريالًا، فكم أسورةً من كلِّ نوعٍ باعت؟', [['الصغيرة', 5], ['الكبيرة', 7]], { sol: ['٥ × ٣,٢٥ + ٧ × ٥,٧٥ = ١٦,٢٥ + ٤٠,٢٥ = ٥٦,٥٠ ✓'], hints: ['خمّنْ عددَ الكبيرةِ وتحقّق.'] }),
    mcq('٩', 'الجدولُ يبيّنُ مبيعاتِ شركةٍ من الأقراصِ المدمجةِ (بالآلاف): ١٤٣٤هـ ١٧,٢، ١٤٣٥هـ ٤,٥، ١٤٣٦هـ ٨,٣، ١٤٣٧هـ ٣,١، ١٤٣٨هـ ٢,٨. في أيِّ السنواتِ كانَ عددُ الأقراصِ المدمجةِ المبيعةِ مساويًا ٣ أمثالِ ما تمَّ بيعُه في عام ١٤٣٨هـ تقريبًا؟', ['١٤٣٤هـ', '١٤٣٥هـ', '١٤٣٦هـ', '١٤٣٧هـ'], 2, { sol: ['٣ × ٢,٨ = ٨,٤ ≈ ٨,٣ (١٤٣٦هـ)'] }),
    mcq('١٠', 'في أيِّ السنواتِ كانَ عددُ الأقراصِ المدمجةِ المبيعةِ أقلَّ بخمسةِ آلافِ قرصٍ عن الأقراصِ المبيعةِ في عام ١٤٣٦هـ تقريبًا؟', ['١٤٣٥هـ', '١٤٣٧هـ', '١٤٣٨هـ'], 1, { sol: ['٨,٣ − ٥ = ٣,٣ ≈ ٣,١ (١٤٣٧هـ)'] }),
    lst('١١', 'أعداد: ما العددانِ اللذانِ حاصلُ ضربِهما ٤٨، والفرقُ بينهما ٨؟', [4, 12], { unordered: true, sol: ['٤ × ١٢ = ٤٨، و١٢ − ٤ = ٨'] }),
    ch('١٢', 'حيتان: الجدولُ يبيّنُ كتلَ بعضِ أنواعِ الحيتان (طن): الحوتُ الأزرق ١٥١,٠، حوتُ القطبِ الشماليّ ٩٥,٠، الحوتُ المجنّح ٦٩,٩، الحوتُ الرماديّ ٣٨,٥، الحوتُ الأحدب ٣٨,١. فهل كتلةُ الحوتِ الأزرقِ تعادلُ ٣، أم ٤، أم ٥ أمثالِ كتلةِ الحوتِ الرماديِّ تقريبًا؟', ['٣', '٤', '٥'], 1, { sol: ['٤ × ٣٨,٥ = ١٥٤ ≈ ١٥١'] })]]] };

